import os,json,urllib.request,urllib.parse
base=os.environ.get('GALAXY_URL','https://usegalaxy.org').rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/padge/phykit/phykit_alignment_based/0.1.0'
url=base+'/api/tools/'+urllib.parse.quote(tool_id, safe='')+'?io_details=true'
req=urllib.request.Request(url, headers={'x-api-key':key})
data=json.load(urllib.request.urlopen(req, timeout=30))

def walk(inputs, indent=0):
    for inp in inputs:
        print('  '*indent + f\"- {inp.get('name')} type={inp.get('type')} label={inp.get('label')} value={inp.get('value')}\")
        if inp.get('options'):
            print('  '*indent+'  options='+repr(inp.get('options'))[:2000])
        for key in ['inputs','cases','test_param','when','section']:
            v=inp.get(key)
            if isinstance(v, list):
                print('  '*indent+f'  {key}:')
                if key=='cases':
                    for c in v:
                        print('  '*(indent+1)+f\"case value={c.get('value')} inputs:\")
                        walk(c.get('inputs',[]), indent+2)
                else:
                    walk(v, indent+1)
            elif isinstance(v, dict):
                print('  '*indent+f'  {key}:')
                walk(v.get('inputs',[]), indent+1)
walk(data.get('inputs',[]))
